WITH valid_subscriptions AS (SELECT *, DAY(end_date) AS end_date_day FROM subscriptions WHERE NOT (monthly_fee BETWEEN 120 AND 150 AND status NOT IN ('EXPIRED', 'ACTIVE', 'CANCELLED'))), agg AS (SELECT QUARTER(start_date) AS start_quarter, COUNT(*) AS num_subscriptions, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list FROM valid_subscriptions GROUP BY QUARTER(start_date)) SELECT start_quarter, num_subscriptions, plan_list FROM agg WHERE num_subscriptions >= 7;
